/* ── Interactive Guided Tour Pro & Mascot Host v2.1 ── */
.wb-tour-addon-widget { display: block; font-family: var(--font-sans, system-ui, -apple-system, sans-serif); }

/* Launcher */
.wb-tour-launcher-btn { position: fixed; z-index: 99990; display: inline-flex; align-items: center; gap: 10px; padding: 8px 16px 8px 10px; background: rgba(15,23,42,0.88); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border: 1px solid rgba(255,255,255,0.18); box-shadow: 0 8px 24px rgba(0,0,0,0.35), 0 0 0 1px rgba(99,102,241,0.3); border-radius: 9999px; color: #f8fafc; font-size: 0.82rem; font-weight: 700; cursor: pointer; transition: transform 0.2s cubic-bezier(0.16,1,0.3,1), box-shadow 0.2s, background 0.2s; user-select: none; }
.wb-tour-launcher-btn:hover { transform: translateY(-2px) scale(1.02); background: rgba(19,27,46,0.98); box-shadow: 0 12px 30px rgba(0,0,0,0.45), 0 0 16px var(--tour-accent,#6366f1); border-color: var(--tour-accent,#6366f1); }
.wb-tour-launcher-btn:active { transform: translateY(0) scale(0.98); }
.wb-tour-launcher-bottom-right { bottom: 24px; right: 24px; }
.wb-tour-launcher-bottom-left  { bottom: 24px; left: 24px; }
.wb-tour-launcher-top-right   { top: 24px; right: 24px; }
.wb-tour-launcher-top-left    { top: 24px; left: 24px; }
.wb-tour-launcher-avatar { width: 32px; height: 32px; border-radius: 50%; overflow: hidden; border: 1.5px solid var(--tour-accent,#6366f1); display: flex; align-items: center; justify-content: center; flex-shrink: 0; background: transparent; }
.wb-tour-launcher-avatar img, .wb-tour-launcher-avatar video, .wb-tour-launcher-avatar canvas { width: 100%; height: 100%; object-fit: cover; object-position: top center; display: block; }
.wb-tour-launcher-icon { font-size: 1.15rem; line-height: 1; }
.wb-tour-launcher-text { letter-spacing: -0.01em; white-space: nowrap; }
.wb-tour-launcher-pulse { display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--tour-accent,#6366f1); box-shadow: 0 0 8px var(--tour-accent,#6366f1); animation: wbTourPulse 1.8s infinite; }
@keyframes wbTourPulse { 0%{transform:scale(.9);opacity:.8}50%{transform:scale(1.4);opacity:1;box-shadow:0 0 12px var(--tour-accent,#6366f1)}100%{transform:scale(.9);opacity:.8} }

/* Overlay + spotlight */
#wb-tour-overlay { position: fixed; inset: 0; z-index: 999990; pointer-events: auto; font-family: var(--font-sans, system-ui, -apple-system, sans-serif); animation: wbTourFadeIn 0.25s ease-out; }
@keyframes wbTourFadeIn { from{opacity:0}to{opacity:1} }
.wb-tour-spotlight-hole { position: fixed; border-radius: 14px; pointer-events: none; transition: top .45s cubic-bezier(.16,1,.3,1), left .45s cubic-bezier(.16,1,.3,1), width .45s cubic-bezier(.16,1,.3,1), height .45s cubic-bezier(.16,1,.3,1), border-radius .3s ease; box-shadow: 0 0 0 9999px rgba(10,16,32,var(--tour-opacity,.78)), 0 0 26px rgba(99,102,241,.55); border: 2px solid var(--tour-accent,#6366f1); outline: 2px dashed rgba(255,255,255,0.35); box-sizing: border-box; }
.wb-tour-spotlight-hole.wb-tour-pulse { animation: wbTourSpotPulse 2.4s ease-in-out infinite; }
@keyframes wbTourSpotPulse { 0%,100%{box-shadow:0 0 0 9999px rgba(10,16,32,var(--tour-opacity,.78)),0 0 26px rgba(99,102,241,.55)} 50%{box-shadow:0 0 0 9999px rgba(10,16,32,var(--tour-opacity,.78)),0 0 42px rgba(99,102,241,.95)} }

/* Presenter */
.wb-tour-presenter-host { position: fixed; z-index: 999996; pointer-events: none; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; filter: drop-shadow(0 20px 35px rgba(0,0,0,.65)); animation: wbTourPresenterFadeIn .4s ease-out, wbTourPresenterBreathe 3.8s ease-in-out infinite; transform-origin: bottom center; }
.wb-tour-presenter-host.wb-tour-pos-bottom-right { bottom: 24px; right: 60px; }
.wb-tour-presenter-host.wb-tour-pos-bottom-left  { bottom: 24px; left: 60px; }
.wb-tour-presenter-host video, .wb-tour-presenter-host img, .wb-tour-presenter-host canvas { display: block; height: 100%; width: auto; max-width: 48vw; object-fit: contain; background: transparent; transform-origin: bottom center; }
.wb-tour-presenter-host.wb-tour-flipped video, .wb-tour-presenter-host.wb-tour-flipped img, .wb-tour-presenter-host.wb-tour-flipped canvas { transform: scaleX(-1); }
.wb-tour-presenter-host::after { content:''; display:block; width:70%; height:16px; margin-top:-8px; background: radial-gradient(ellipse at center, rgba(0,0,0,.65) 0%, rgba(0,0,0,0) 72%); border-radius:50%; pointer-events:none; }
@keyframes wbTourPresenterFadeIn { from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)} }
@keyframes wbTourPresenterBreathe { 0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-7px) scale(1.012)} }
@media (max-width:768px){ .wb-tour-presenter-host{max-height:240px !important; right:16px !important; bottom:16px !important;} }

/* Card */
.wb-tour-card { position: fixed; z-index: 999995; width: 380px; max-width: calc(100vw - 32px); border-radius: 20px; box-sizing: border-box; padding: 22px 24px; transition: top .45s cubic-bezier(.16,1,.3,1), left .45s cubic-bezier(.16,1,.3,1), opacity .2s, transform .2s; box-shadow: 0 24px 50px rgba(0,0,0,.65), 0 0 1px rgba(255,255,255,.2); }
.wb-tour-theme-glass { background: rgba(19,27,46,.92); backdrop-filter: blur(18px); -webkit-backdrop-filter: blur(18px); border: 1px solid rgba(255,255,255,.15); color: #f8fafc; }
.wb-tour-theme-dark { background: #0f172a; border: 1px solid rgba(255,255,255,.1); color: #f8fafc; }
.wb-tour-theme-light { background: #fff; border: 1px solid rgba(0,0,0,.1); box-shadow: 0 20px 45px rgba(0,0,0,.15); color: #0f172a; }
.wb-tour-avatar-container { display: flex; align-items: center; justify-content: center; overflow: hidden; }
.wb-tour-avatar-peeking { position: absolute; top: -38px; left: 20px; width: 58px; height: 58px; border-radius: 50%; background: transparent; border: 2.5px solid var(--tour-accent,#6366f1); box-shadow: 0 4px 16px rgba(0,0,0,.45); animation: wbTourBob 2.8s ease-in-out infinite; }
.wb-tour-avatar-companion { position: absolute; bottom: 0; left: calc(100% + 14px); height: 300px; width: auto; pointer-events: none; filter: drop-shadow(0 12px 24px rgba(0,0,0,.45)); animation: wbTourPresenterBreathe 3.5s ease-in-out infinite; }
.wb-tour-avatar-companion video, .wb-tour-avatar-companion img, .wb-tour-avatar-companion canvas { height: 100%; width: auto; object-fit: contain; display: block; }
.wb-tour-avatar-badge { width: 26px; height: 26px; border-radius: 50%; overflow: hidden; border: 1.5px solid var(--tour-accent,#6366f1); display: inline-flex; vertical-align: middle; margin-right: 6px; background: transparent; }
.wb-tour-avatar-canvas, .wb-tour-avatar-media { width: 100%; height: 100%; object-fit: cover; display: block; }
@keyframes wbTourBob { 0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)} }

/* Card Header & Controls */
.wb-tour-card-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; gap: 8px; }
.wb-tour-badge-pill { display: inline-flex; align-items: center; gap: 5px; padding: 3px 9px; border-radius: 20px; font-size: .68rem; font-weight: 800; text-transform: uppercase; letter-spacing: .05em; background: rgba(99,102,241,.18); color: #c7d2fe; border: 1px solid rgba(99,102,241,.35); }
.wb-tour-audio-pill { display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px; border-radius: 12px; font-size: .68rem; font-weight: 700; background: rgba(16,185,129,.18); color: #6ee7b7; border: 1px solid rgba(16,185,129,.35); cursor: pointer; transition: all .15s; }
.wb-tour-audio-pill:hover { background: rgba(16,185,129,.28); }
.wb-tour-audio-pill.is-muted { background: rgba(148,163,184,.15); color: #94a3b8; border-color: rgba(148,163,184,.25); }
.wb-tour-audio-wave { display: inline-block; animation: wbVoicePulse 1.2s infinite ease-in-out; }
@keyframes wbVoicePulse { 0%,100%{opacity:.6;transform:scaleY(.8)} 50%{opacity:1;transform:scaleY(1.2)} }
.wb-tour-step-counter { font-size: .72rem; font-weight: 700; color: #94a3b8; margin-left: auto; }
.wb-tour-close-btn { background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 1.1rem; padding: 2px 6px; border-radius: 6px; line-height: 1; transition: color .15s, background .15s; }
.wb-tour-close-btn:hover { color: #f87171; background: rgba(239,68,68,.1); }

.wb-tour-card-title { font-size: 1.05rem; font-weight: 800; margin: 0 0 8px 0; line-height: 1.3; letter-spacing: -.02em; }
.wb-tour-card-desc { font-size: .84rem; line-height: 1.55; color: #cbd5e1; margin: 0 0 16px 0; }
.wb-tour-theme-light .wb-tour-card-desc { color: #475569; }
.wb-tour-target-pill { display: inline-flex; align-items: center; gap: 4px; font-size: .66rem; font-weight: 700; color: #94a3b8; margin-bottom: 10px; padding: 2px 8px; border-radius: 6px; background: rgba(148,163,184,.12); }
.wb-tour-progress-bar { display: flex; align-items: center; gap: 6px; margin-bottom: 16px; }
.wb-tour-dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(255,255,255,.2); transition: all .25s ease; }
.wb-tour-theme-light .wb-tour-dot { background: rgba(0,0,0,.15); }
.wb-tour-dot.active { width: 22px; border-radius: 4px; background: var(--tour-accent,#6366f1); box-shadow: 0 0 8px var(--tour-accent,#6366f1); }
.wb-tour-card-actions { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 10px; border-top: 1px solid rgba(255,255,255,.08); }
.wb-tour-theme-light .wb-tour-card-actions { border-top: 1px solid rgba(0,0,0,.08); }
.wb-tour-skip-btn { background: none; border: none; color: #94a3b8; font-size: .76rem; font-weight: 600; cursor: pointer; padding: 6px 10px; border-radius: 6px; transition: color .15s; }
.wb-tour-skip-btn:hover { color: #fff; }
.wb-tour-nav-btns { display: flex; align-items: center; gap: 6px; }
.wb-tour-btn { padding: 7px 14px; border-radius: 8px; font-size: .78rem; font-weight: 700; cursor: pointer; border: none; transition: all .15s ease; }
.wb-tour-btn-back { background: rgba(255,255,255,.08); color: #cbd5e1; border: 1px solid rgba(255,255,255,.12); }
.wb-tour-theme-light .wb-tour-btn-back { background: #f1f5f9; color: #475569; border: 1px solid #e2e8f0; }
.wb-tour-btn-back:hover:not(:disabled) { background: rgba(255,255,255,.15); color: #fff; }
.wb-tour-btn-back:disabled { opacity: .35; cursor: not-allowed; }
.wb-tour-btn-next { background: var(--tour-accent,#6366f1); color: #fff; box-shadow: 0 4px 14px rgba(99,102,241,.4); }
.wb-tour-btn-next:hover { filter: brightness(1.1); transform: translateY(-1px); }
.wb-tour-btn-next:active { transform: translateY(0); }
@media (prefers-reduced-motion: reduce) { .wb-tour-card, .wb-tour-spotlight-hole, .wb-tour-presenter-host, .wb-tour-launcher-btn { transition: none !important; animation: none !important; } }

