/* Interactive Guided Tour Pro & Mascot Host v2.1 */
function onMount(el, props) {
  var root = el.querySelector('.wb-tour-addon-widget');
  if (!root) return;

  var esc = function (s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  };

  var steps = Array.isArray(props.steps) ? props.steps : [];
  if (steps.length === 0) {
    steps = [
      { targetSelector: '#home-nav-1, header, nav', title: 'Welcome! 👋', content: 'Explore our top navigation to discover sections and services.', placement: 'bottom' },
      { targetSelector: '#home-registration-form-1, #home-contact-1, form', title: 'Quick Registration 📝', content: 'Complete this form to reserve your slot instantly.', placement: 'top' },
      { targetSelector: '#home-footer-1, footer', title: 'Contact & Support 📍', content: 'Find official contact details, addresses, and social links here.', placement: 'top' }
    ];
  }

  var currentStep = 0;
  var overlayEl = null, spotlightEl = null, cardEl = null, presenterHostEl = null;
  var isTourActive = false;
  var activeCleanups = [];
  var activeAudio = null;
  var isMuted = false;

  var accentColor = props.accentColor || '#6366f1';
  var cardTheme = props.cardTheme || 'glass';
  var backdropOpacity = parseFloat(props.backdropOpacity) || 0.75;
  var spotlightPad = parseInt(props.spotlightPadding) || 10;
  var showAvatar = props.showAvatar !== false && props.showAvatar !== 'false';
  var avatarUrlDefault = (props.avatarUrl || '').trim();
  var avatarNameDefault = esc(props.avatarName || 'Guide');
  var avatarStyleDefault = props.avatarStyle || 'presenter-right';
  var avatarHeightDefault = parseInt(props.avatarHeight) || 380;
  var avatarFlip = props.avatarFlip === true || props.avatarFlip === 'true';
  var removeGreen = props.removeGreenScreen === true || props.removeGreenScreen === 'true';
  var greenColor = props.greenKeyColor || '#00ff00';
  var greenTol = parseFloat(props.greenKeyTolerance) || 45;
  var tourBadge = esc(props.tourBadge || 'GUIDED TOUR');
  var storageKey = props.tourStorageKey || 'aether_tour_completed';
  var spotlightPulse = props.spotlightPulse !== false && props.spotlightPulse !== 'false';
  var advanceOnClick = props.stepAdvanceOnClick === true || props.stepAdvanceOnClick === 'true';
  var enableVoiceOver = props.enableVoiceOver !== false && props.enableVoiceOver !== 'false';
  var enableRecording = props.enableRecording === true || props.enableRecording === 'true';
  var mediaRecorder = null;
  var recordedChunks = [];
  var recordingMimeType = '';
  var voiceVolume = Math.min(100, Math.max(0, parseInt(props.voiceVolume) || 100)) / 100;
  var autoAdvanceOnAudio = props.autoAdvanceOnAudioEnd === true || props.autoAdvanceOnAudioEnd === 'true';

  root.style.setProperty('--tour-accent', accentColor);

  function resolveStepAvatar(step) {
    return {
      url: (step && step.stepAvatarUrl && step.stepAvatarUrl.trim()) ? step.stepAvatarUrl.trim() : avatarUrlDefault,
      name: esc((step && step.stepAvatarName && step.stepAvatarName.trim()) ? step.stepAvatarName.trim() : (props.avatarName || 'Guide')),
      style: (step && step.stepAvatarStyle && step.stepAvatarStyle.trim()) ? step.stepAvatarStyle.trim() : avatarStyleDefault,
      height: (step && step.stepAvatarHeight && parseInt(step.stepAvatarHeight) > 0) ? parseInt(step.stepAvatarHeight) : avatarHeightDefault
    };
  }

  function getSupportedMimeType() {
    var types = ['video/mp4;codecs=avc1', 'video/webm;codecs=vp9', 'video/webm'];
    for (var i = 0; i < types.length; i++) {
      if (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported(types[i])) return types[i];
    }
    return 'video/webm';
  }

  function startRecording(callback) {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getDisplayMedia) {
      alert('Screen recording is not supported in this browser. Please use Chrome or Edge.');
      if (callback) callback(false);
      return;
    }
    recordedChunks = [];
    recordingMimeType = getSupportedMimeType();
    navigator.mediaDevices.getDisplayMedia({
      video: { displaySurface: 'browser', frameRate: 30 },
      audio: false,
      preferCurrentTab: true,
      selfBrowserSurface: 'include'
    }).then(function(stream) {
      try {
        mediaRecorder = new MediaRecorder(stream, { mimeType: recordingMimeType });
      } catch(e) {
        mediaRecorder = new MediaRecorder(stream);
        recordingMimeType = 'video/webm';
      }
      mediaRecorder.ondataavailable = function(e) {
        if (e.data && e.data.size > 0) recordedChunks.push(e.data);
      };
      mediaRecorder.onstop = function() {
        stream.getTracks().forEach(function(t) { t.stop(); });
        var blob = new Blob(recordedChunks, { type: recordingMimeType });
        var ext = recordingMimeType.startsWith('video/mp4') ? 'mp4' : 'webm';
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url;
        a.download = 'site-tour.' + ext;
        document.body.appendChild(a);
        a.click();
        setTimeout(function() {
          try { document.body.removeChild(a); } catch(_) {}
          URL.revokeObjectURL(url);
        }, 3000);
      };
      mediaRecorder.start(1000);
      if (callback) callback(true);
    }).catch(function(err) {
      console.warn('Tour recording cancelled or failed:', err);
      if (callback) callback(false);
    });
  }

  function stopRecording() {
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      try { mediaRecorder.stop(); } catch(_) {}
      mediaRecorder = null;
    }
  }

  function stopAudio() {
    if (activeAudio) {
      try {
        activeAudio.pause();
        activeAudio.currentTime = 0;
        activeAudio.onended = null;
      } catch(_) {}
      activeAudio = null;
    }
  }

  function playStepAudio(step) {
    stopAudio();
    if (!enableVoiceOver || isMuted || !step || !step.stepAudioUrl || !step.stepAudioUrl.trim()) return;
    try {
      var audio = new Audio(step.stepAudioUrl.trim());
      audio.volume = voiceVolume;
      if (autoAdvanceOnAudio) {
        audio.onended = function () {
          if (isTourActive) nextStep();
        };
      }
      var promise = audio.play();
      if (promise && typeof promise.catch === 'function') {
        promise.catch(function (err) {
          console.warn('Tour voice-over playback notice:', err);
        });
      }
      activeAudio = audio;
    } catch(err) {
      console.warn('Tour voice audio init notice:', err);
    }
  }

  function createAvatarNode(url, name, style, isGreen, keyHex, tolVal, targetH) {
    var wrapper = document.createElement('div');
    wrapper.className = 'wb-tour-avatar-container wb-tour-avatar-' + style;
    if (!url) return wrapper;

    var isVideo = /\.(mp4|webm|ogg|mov)(\?.*)?$/i.test(url);
    var hex = keyHex.replace('#', '');
    if (hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
    var num = parseInt(hex, 16) || 0x00ff00;
    var targetR = (num >> 16) & 255, targetG = (num >> 8) & 255, targetB = num & 255;
    var feather = 12;

    if (isVideo) {
      var video = document.createElement('video');
      video.src = url; video.autoplay = true; video.loop = true; video.muted = true; video.playsInline = true;
      video.setAttribute('playsinline',''); video.setAttribute('webkit-playsinline',''); video.crossOrigin = 'anonymous';

      if (isGreen) {
        var canvas = document.createElement('canvas');
        canvas.className = 'wb-tour-avatar-canvas'; wrapper.appendChild(canvas);
        var animId = null, ctx = null;
        var renderLoop = function () {
          if (!video || video.paused || video.ended) return;
          if (video.videoWidth && video.videoHeight) {
            if (!ctx) ctx = canvas.getContext('2d', { willReadFrequently: true });
            var w = video.videoWidth, h = video.videoHeight;
            if (canvas.width !== w || canvas.height !== h) {
              var maxDim = Math.max(480, targetH || 380);
              var scale = Math.min(1, maxDim / Math.max(w, h));
              canvas.width = Math.round(w * scale); canvas.height = Math.round(h * scale);
            }
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            var frame = ctx.getImageData(0, 0, canvas.width, canvas.height);
            var d = frame.data, len = d.length;
            for (var i = 0; i < len; i += 4) {
              var r = d[i], g = d[i+1], b = d[i+2];
              var dist = Math.sqrt((r-targetR)*(r-targetR)+(g-targetG)*(g-targetG)+(b-targetB)*(b-targetB));
              var norm = (dist / 441.67) * 100;
              if (norm < tolVal - feather) { d[i+3] = 0; }
              else if (norm < tolVal) { d[i+3] = Math.round(((norm-(tolVal-feather))/feather)*255); var m = Math.max(r,b); if (g > m) d[i+1] = m; }
              else if (g > targetG*0.7 && g > r*1.25 && g > b*1.25) { d[i+1] = Math.max(r,b); }
            }
            ctx.putImageData(frame, 0, 0);
          }
          animId = requestAnimationFrame(renderLoop);
        };
        video.addEventListener('play', function () { cancelAnimationFrame(animId); animId = requestAnimationFrame(renderLoop); });
        var cleanup = function () { cancelAnimationFrame(animId); video.pause(); video.src = ''; };
        wrapper.__cleanup = cleanup; activeCleanups.push(cleanup);
        video.play().catch(function(){});
      } else {
        video.className = 'wb-tour-avatar-media'; wrapper.appendChild(video);
        var cs = function () { video.pause(); video.src = ''; };
        wrapper.__cleanup = cs; activeCleanups.push(cs);
        video.play().catch(function(){});
      }
    } else {
      if (isGreen) {
        var img = new Image(); img.crossOrigin = 'anonymous'; img.src = url;
        var canvasImg = document.createElement('canvas'); canvasImg.className = 'wb-tour-avatar-canvas'; wrapper.appendChild(canvasImg);
        img.onload = function () {
          var ctxImg = canvasImg.getContext('2d', { willReadFrequently: true });
          var maxDim = Math.max(480, targetH || 380);
          var scale = Math.min(1, maxDim / Math.max(img.width, img.height));
          canvasImg.width = Math.round(img.width * scale); canvasImg.height = Math.round(img.height * scale);
          ctxImg.drawImage(img, 0, 0, canvasImg.width, canvasImg.height);
          var frame = ctxImg.getImageData(0, 0, canvasImg.width, canvasImg.height);
          var d = frame.data, len = d.length;
          for (var i = 0; i < len; i += 4) {
            var r = d[i], g = d[i+1], b = d[i+2];
            var dist = Math.sqrt((r-targetR)*(r-targetR)+(g-targetG)*(g-targetG)+(b-targetB)*(b-targetB));
            var norm = (dist/441.67)*100;
            if (norm < tolVal - feather) { d[i+3] = 0; }
            else if (norm < tolVal) { d[i+3] = Math.round(((norm-(tolVal-feather))/feather)*255); var m = Math.max(r,b); if (g > m) d[i+1] = m; }
          }
          ctxImg.putImageData(frame, 0, 0);
        };
      } else {
        var imgTag = document.createElement('img'); imgTag.className = 'wb-tour-avatar-media'; imgTag.src = url; imgTag.alt = name;
        wrapper.appendChild(imgTag);
      }
    }
    return wrapper;
  }

  function clearActiveCleanups() {
    for (var i = 0; i < activeCleanups.length; i++) { try { activeCleanups[i](); } catch(_){} }
    activeCleanups = [];
    stopAudio();
  }

  function createOverlay() {
    var prev = document.getElementById('wb-tour-overlay');
    if (prev) prev.remove();
    overlayEl = document.createElement('div');
    overlayEl.id = 'wb-tour-overlay';
    overlayEl.style.setProperty('--tour-accent', accentColor);
    overlayEl.style.setProperty('--tour-opacity', backdropOpacity);
    spotlightEl = document.createElement('div');
    spotlightEl.className = 'wb-tour-spotlight-hole' + (spotlightPulse ? ' wb-tour-pulse' : '');
    overlayEl.appendChild(spotlightEl);
    cardEl = document.createElement('div');
    cardEl.className = 'wb-tour-card wb-tour-theme-' + cardTheme;
    overlayEl.appendChild(cardEl);
    document.body.appendChild(overlayEl);
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('resize', onViewportChange);
    window.addEventListener('scroll', onViewportChange, true);
  }

  function removeOverlay() {
    isTourActive = false;
    clearActiveCleanups();
    window.removeEventListener('keydown', onKeyDown);
    window.removeEventListener('resize', onViewportChange);
    window.removeEventListener('scroll', onViewportChange, true);
    if (overlayEl) { overlayEl.remove(); overlayEl = spotlightEl = cardEl = presenterHostEl = null; }
  }

  function onKeyDown(e) {
    if (!isTourActive) return;
    if (e.key === 'Escape') endTour(false);
    else if (e.key === 'ArrowRight' || e.key === 'Enter') nextStep();
    else if (e.key === 'ArrowLeft') prevStep();
    else if (e.key === 'Home') goToStep(0);
    else if (e.key === 'End') goToStep(steps.length - 1);
  }

  var scrollTimer = null;
  function onViewportChange() {
    if (!isTourActive) return;
    clearTimeout(scrollTimer);
    scrollTimer = setTimeout(function () { updatePositions(currentStep); }, 40);
  }

  function findTargetElement(selector) {
    if (!selector) return null;
    var selectors = selector.split(',').map(function(s){ return s.trim(); }).filter(Boolean);
    for (var i = 0; i < selectors.length; i++) {
      try {
        var sel = selectors[i];
        var f = document.querySelector(sel);
        if (f && f.offsetParent !== null) return f;
      } catch(_) {}
    }
    return null;
  }

  function updatePositions(stepIdx) {
    if (!isTourActive || !cardEl || !spotlightEl) return;
    var step = steps[stepIdx];
    if (!step) return;
    var target = findTargetElement(step.targetSelector);
    var rect;
    if (target) {
      rect = target.getBoundingClientRect();
      var top = Math.max(4, rect.top - spotlightPad);
      var left = Math.max(4, rect.left - spotlightPad);
      var width = rect.width + spotlightPad * 2;
      var height = rect.height + spotlightPad * 2;
      spotlightEl.style.top = top + 'px';
      spotlightEl.style.left = left + 'px';
      spotlightEl.style.width = width + 'px';
      spotlightEl.style.height = height + 'px';
      spotlightEl.style.display = 'block';
      if (advanceOnClick) {
        target.style.cursor = 'pointer';
        target.addEventListener('click', function onc(e){
          target.removeEventListener('click', onc);
          var link = target.tagName === 'A' ? target : target.querySelector('a');
          var href = link ? link.getAttribute('href') : null;
          if (href && !href.startsWith('#') && (href.startsWith('?') || href.includes('.html'))) {
            try {
              sessionStorage.setItem('aether_tour_cross_resume', JSON.stringify({
                active: true,
                stepIndex: currentStep + 1,
                tourProps: props,
                timestamp: Date.now()
              }));
            } catch(_) {}
            if (window.aetherApp && typeof window.aetherApp.navigateToPage === 'function') {
              e.preventDefault();
              window.aetherApp.navigateToPage(href).then(function() {
                setTimeout(function() {
                  currentStep < steps.length - 1 ? nextStep() : endTour(true);
                }, 250);
              });
              return;
            }
          }
          currentStep < steps.length - 1 ? nextStep() : endTour(true);
        });
      }
    } else {
      spotlightEl.style.display = 'none';
      rect = { top: window.innerHeight/2, bottom: window.innerHeight/2, left: window.innerWidth/2, right: window.innerWidth/2, width: 0, height: 0 };
    }

    var placement = step.placement || 'auto';
    var cardW = cardEl.offsetWidth || 380;
    var cardH = cardEl.offsetHeight || 220;
    var cTop, cLeft;
    if (placement === 'auto') {
      var spaceBelow = window.innerHeight - rect.bottom;
      var spaceAbove = rect.top;
      placement = (spaceBelow >= cardH + 24) ? 'bottom' : (spaceAbove >= cardH + 24 ? 'top' : 'bottom');
    }
    if (placement === 'bottom') { cTop = rect.bottom + 16; cLeft = rect.left + rect.width/2 - cardW/2; }
    else if (placement === 'top') { cTop = rect.top - cardH - 16; cLeft = rect.left + rect.width/2 - cardW/2; }
    else if (placement === 'right' && rect.right + cardW + 20 < window.innerWidth) { cTop = rect.top + rect.height/2 - cardH/2; cLeft = rect.right + 16; }
    else if (placement === 'left' && rect.left - cardW - 20 > 0) { cTop = rect.top + rect.height/2 - cardH/2; cLeft = rect.left - cardW - 16; }
    else { cTop = window.innerHeight/2 - cardH/2; cLeft = window.innerWidth/2 - cardW/2; }
    cLeft = Math.max(16, Math.min(window.innerWidth - cardW - 16, cLeft));
    cTop = Math.max(48, Math.min(window.innerHeight - cardH - 16, cTop));
    cardEl.style.top = Math.round(cTop) + 'px';
    cardEl.style.left = Math.round(cLeft) + 'px';
  }

  function renderCardContent(step, idx) {
    var isLast = idx === steps.length - 1, isFirst = idx === 0;
    cardEl.querySelectorAll('.wb-tour-avatar-container').forEach(function(c){ if (typeof c.__cleanup === 'function') c.__cleanup(); });

    var dotsHtml = '<div class="wb-tour-progress-bar">';
    for (var i = 0; i < steps.length; i++) dotsHtml += '<span class="wb-tour-dot ' + (i===idx?'active':'') + '"></span>';
    dotsHtml += '</div>';
    var iconHtml = step.stepIcon ? '<span style="font-size:1.15rem;margin-right:6px;">' + esc(step.stepIcon) + '</span>' : '';
    var labelHtml = step.targetLabel ? '<div class="wb-tour-target-pill">🎯 ' + esc(step.targetLabel) + '</div>' : '';

    var hasAudio = !!(enableVoiceOver && step.stepAudioUrl && step.stepAudioUrl.trim());
    var audioBtnHtml = hasAudio ? '<button type="button" class="wb-tour-audio-pill ' + (isMuted ? 'is-muted' : '') + '" title="Toggle voice narration"><span>' + (isMuted ? '🔇 Muted' : '🔊 Voice') + '</span><span class="wb-tour-audio-wave">ılıl</span></button>' : '';

    cardEl.innerHTML =
      '<div class="wb-tour-card-header">' +
        '<span class="wb-tour-badge-pill"><span class="wb-tour-avatar-slot"></span>' + tourBadge + '</span>' +
        audioBtnHtml +
        '<span class="wb-tour-step-counter">Step ' + (idx+1) + ' of ' + steps.length + '</span>' +
        '<button type="button" class="wb-tour-close-btn" title="Exit Tour">✕</button>' +
      '</div>' +
      labelHtml +
      '<h4 class="wb-tour-card-title">' + iconHtml + esc(step.title || 'Step ' + (idx+1)) + '</h4>' +
      '<p class="wb-tour-card-desc">' + esc(step.content || '') + '</p>' +
      dotsHtml +
      '<div class="wb-tour-card-actions">' +
        '<button type="button" class="wb-tour-skip-btn">Skip Tour</button>' +
        '<div class="wb-tour-nav-btns">' +
          '<button type="button" class="wb-tour-btn wb-tour-btn-back" ' + (isFirst?'disabled':'') + '>Back</button>' +
          '<button type="button" class="wb-tour-btn wb-tour-btn-next">' + (isLast?'Finish 🎉':'Next →') + '</button>' +
        '</div>' +
      '</div>';

    var av = resolveStepAvatar(step);
    if (showAvatar && av.url && (av.style === 'badge' || av.style === 'peeking' || av.style === 'companion')) {
      var node = createAvatarNode(av.url, av.name, av.style, removeGreen, greenColor, greenTol, 200);
      if (av.style === 'badge') {
        var slot = cardEl.querySelector('.wb-tour-avatar-slot');
        if (slot) slot.appendChild(node);
      } else {
        cardEl.insertBefore(node, cardEl.firstChild);
      }
    }

    var audioBtn = cardEl.querySelector('.wb-tour-audio-pill');
    if (audioBtn) {
      audioBtn.onclick = function () {
        isMuted = !isMuted;
        if (isMuted) {
          stopAudio();
          audioBtn.classList.add('is-muted');
          audioBtn.innerHTML = '<span>🔇 Muted</span>';
        } else {
          audioBtn.classList.remove('is-muted');
          audioBtn.innerHTML = '<span>🔊 Voice</span><span class="wb-tour-audio-wave">ılıl</span>';
          playStepAudio(step);
        }
      };
    }

    cardEl.querySelector('.wb-tour-close-btn').onclick = function(){ endTour(false); };
    cardEl.querySelector('.wb-tour-skip-btn').onclick = function(){ endTour(false); };
    cardEl.querySelector('.wb-tour-btn-back').onclick = function(){ prevStep(); };
    cardEl.querySelector('.wb-tour-btn-next').onclick = function(){ isLast ? endTour(true) : nextStep(); };
  }

  function mountPresenter(step) {
    if (presenterHostEl) { presenterHostEl.remove(); presenterHostEl = null; }
    var av = resolveStepAvatar(step);
    if (!showAvatar || !av.url || (av.style !== 'presenter-right' && av.style !== 'presenter-left')) return;
    presenterHostEl = document.createElement('div');
    var posClass = av.style === 'presenter-left' ? 'wb-tour-pos-bottom-left' : 'wb-tour-pos-bottom-right';
    presenterHostEl.className = 'wb-tour-presenter-host ' + posClass + (avatarFlip ? ' wb-tour-flipped' : '');
    presenterHostEl.style.height = av.height + 'px';
    var node = createAvatarNode(av.url, av.name, 'presenter', removeGreen, greenColor, greenTol, av.height);
    presenterHostEl.appendChild(node);
    overlayEl.appendChild(presenterHostEl);
  }

  function goToStep(idx) {
    if (idx < 0 || idx >= steps.length) return;
    currentStep = idx;
    var step = steps[idx];

    // Multi-page cross-navigation check
    if (step && step.navigateToUrl && typeof step.navigateToUrl === 'string' && step.navigateToUrl.trim()) {
      var navTarget = step.navigateToUrl.trim();
      if (navTarget !== '#' && navTarget !== 'custom' && navTarget !== '') {
        var currSearch = window.location.search || '';
        var currPath = window.location.pathname.split('/').pop() || 'index.html';
        var isCurrent = (navTarget.startsWith('?') && currSearch === navTarget) ||
                        (currPath === navTarget && !currSearch) ||
                        (navTarget === 'index.html' && (!currSearch || currSearch === '?page=index'));
        if (!isCurrent) {
          try {
            sessionStorage.setItem('aether_tour_cross_resume', JSON.stringify({
              active: true,
              stepIndex: idx,
              tourProps: props,
              timestamp: Date.now()
            }));
          } catch(_) {}

          if (window.aetherApp && typeof window.aetherApp.navigateToPage === 'function') {
            window.aetherApp.navigateToPage(navTarget).then(function() {
              setTimeout(function () { goToStep(idx); }, 250);
            });
            return;
          } else if (window.aetherApp && typeof window.aetherApp.initPublicView === 'function') {
            var targetFull = new URL(navTarget, window.location.href);
            window.history.pushState(null, '', targetFull.href);
            window.aetherApp.initPublicView().then(function() {
              setTimeout(function () { goToStep(idx); }, 250);
            });
            return;
          }
          window.location.href = navTarget;
          return;
        }
      }
    }

    var target = findTargetElement(step.targetSelector);
    if (target) { try { target.scrollIntoView({ behavior:'smooth', block:'center', inline:'nearest' }); } catch(_){} }
    renderCardContent(step, idx);
    mountPresenter(step);
    playStepAudio(step);
    setTimeout(function () { updatePositions(idx); }, 150);
  }

  function nextStep() { currentStep < steps.length - 1 ? goToStep(currentStep + 1) : endTour(true); }
  function prevStep() { currentStep > 0 && goToStep(currentStep - 1); }

  function startTour() {
    if (steps.length === 0) return;
    isTourActive = true;
    createOverlay();
    goToStep(0);
  }

  function endTour(completed) {
    try { sessionStorage.removeItem('aether_tour_cross_resume'); } catch(_) {}
    stopAudio();
    removeOverlay();
    if (completed && storageKey) { try { localStorage.setItem(storageKey, 'true'); } catch(_){} }
    if (completed && window.aetherApp && window.aetherApp.canvas && typeof window.aetherApp.canvas.showToast === 'function') {
      window.aetherApp.canvas.showToast('🎉 Tour completed! Welcome aboard.', 'success');
    }
  }

  var launcherBtn = root.querySelector('.wb-tour-launcher-btn');
  if (launcherBtn) {
    launcherBtn.addEventListener('click', function (e) { e.stopPropagation(); startTour(); });
    if (showAvatar && avatarUrlDefault) {
      var launcherSlot = launcherBtn.querySelector('.wb-tour-launcher-avatar');
      if (launcherSlot) {
        launcherSlot.innerHTML = '';
        launcherSlot.appendChild(createAvatarNode(avatarUrlDefault, avatarNameDefault, 'launcher', removeGreen, greenColor, greenTol, 64));
      }
    }
  }

  // Record & Play button (only if enableRecording is on)
  if (enableRecording) {
    var recBtn = document.createElement('button');
    recBtn.type = 'button';
    recBtn.className = 'wb-tour-record-btn';
    recBtn.title = 'Records your browser tab + tour. Nothing is uploaded — file saves to your device.';
    recBtn.innerHTML = '🎬 Record & Play Tour';
    recBtn.style.cssText = [
      'display:inline-flex',
      'align-items:center',
      'gap:6px',
      'margin-top:8px',
      'padding:8px 16px',
      'border:none',
      'border-radius:20px',
      'background:#e53935',
      'color:#fff',
      'font-size:13px',
      'font-weight:600',
      'cursor:pointer',
      'box-shadow:0 2px 8px rgba(229,57,53,0.35)',
      'transition:opacity .2s'
    ].join(';');
    recBtn.onmouseenter = function() { recBtn.style.opacity = '0.85'; };
    recBtn.onmouseleave = function() { recBtn.style.opacity = '1'; };
    recBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      startRecording(function(started) {
        if (started) startTour();
      });
    });
    var launcherWrap = root.querySelector('.wb-tour-launcher');
    if (launcherWrap) {
      launcherWrap.appendChild(recBtn);
    } else {
      root.appendChild(recBtn);
    }
  }

  // Cross-page tour resume
  try {
    var resumeData = JSON.parse(sessionStorage.getItem('aether_tour_cross_resume') || 'null');
    if (resumeData && resumeData.active && (Date.now() - resumeData.timestamp < 300000)) {
      sessionStorage.removeItem('aether_tour_cross_resume');
      setTimeout(function () {
        if (!isTourActive) {
          startTour();
          goToStep(resumeData.stepIndex || 0);
        }
      }, 400);
    }
  } catch(_) {}

  if (props.autoStart === true || props.autoStart === 'true') {
    var done = false;
    try { done = !!localStorage.getItem(storageKey); } catch(_){}
    if (!done) setTimeout(function () { if (!isTourActive) startTour(); }, 1000);
  }

  el.__wbDestroy = function () {
    stopAudio();
    removeOverlay();
  };
}
